package geoip

import (
	"compress/gzip"
	"encoding/base64"
	"io"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// These are gzip-compressed copies of MaxMind\'s fake GeoIP test databases.
// Source: https://github.com/maxmind/MaxMind-DB/tree/main/test-data
// Retrieved 2026-09-07. The upstream repository and test data are dual-licensed
// under Apache-2.0 or MIT; see its LICENSE-APACHE and LICENSE-MIT files.
// The fixtures contain synthetic example data, not production GeoIP data.

const countryFixtureGzipBase64 = ""

const asnFixtureGzipBase64 = ""

const cityFixtureGzipBase64 = ""

func writeFixture(t *testing.T, name string) string {
	t.Helper()
	encoded := map[string]string{
		"wrong-country":    wrongCountryFixtureGzipBase64,
		"optional-country": optionalCountryFixtureGzipBase64,
		"country":          countryFixtureGzipBase64,
		"asn":              asnFixtureGzipBase64,
		"city":             cityFixtureGzipBase64,
	}[name]
	compressed, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		t.Fatal(err)
	}
	zr, err := gzip.NewReader(strings.NewReader(string(compressed)))
	if err != nil {
		t.Fatal(err)
	}
	defer zr.Close()
	path := filepath.Join(t.TempDir(), name+".mmdb")
	out, err := os.Create(path)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := io.Copy(out, zr); err != nil {
		out.Close()
		t.Fatal(err)
	}
	if err := out.Close(); err != nil {
		t.Fatal(err)
	}
	return path
}
